import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "siteUrl", label: "Site URL", value: "https://example.com", full: true })}${field({ id: "sitemap", label: "Sitemap URL", value: "https://example.com/sitemap.xml", full: true })}${select({id: "crawlMode",label: "Default crawler access",value: "allow",options: [{ label: "Allow all public pages", value: "allow" },{ label: "Block all crawling", value: "block" }]})}${textarea({ id: "disallow", label: "Disallowed paths", value: "/tmp/\n/search/\n?preview=", help: "One path or pattern per line. Leave blank when everything public can be crawled." })}${checkbox({ id: "aiNote", label: "Add AI crawler policy comment", checked: true })}</div>`,generate(root) {const siteUrl = normalizeUrl(root.querySelector("#siteUrl").value).replace(/\/$/, "");const sitemap = normalizeUrl(root.querySelector("#sitemap").value);const blockAll = root.querySelector("#crawlMode").value === "block";const disallow = root.querySelector("#disallow").value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);const lines = ["User-agent: *"];if (blockAll) {lines.push("Disallow: /");} else {lines.push("Allow: /");disallow.forEach((path) => lines.push(`Disallow: ${path}`));}if (root.querySelector("#aiNote").checked) {lines.push("", "# AI crawler policy: public pages are available unless a path is disallowed above.");}lines.push("", `Sitemap: ${sitemap || `${siteUrl}/sitemap.xml`}`);return { output: lines.join("\n") };}};